{"requirements": [
    {
        "id": 1,
        "text": "The game shall be designed for two players."
    },
    {
        "id": 2,
        "text": "The game shall consist of two rectangular paddles, each with a size of 1 x 4 blocks."
    },
    {
        "id": 3,
        "text": "The ball's direction shall change every time the ball hits a paddle, the top or bottom of the board."
    },
    {
        "id": 4,
        "text": "The new direction of the ball shall be computed with the same angle of reflection as the angle of incidence."
    },
    {
        "id": 5,
        "text": "The ball shall move in a straight line from the center of the screen toward the left side of the board with a speed of 5 pixels/sec when the game starts."
    },
    {
        "id": 6,
        "text": "The blocks composing the rectangular board shall have a size of 10 x 10 pixels."
    },
    {
        "id": 7,
        "text": "The paddles shall be located on the left and right side of the board."
    },
    {
        "id": 8,
        "text": "The paddles shall be located in the middle of the vertical sides when the game starts."
    },
    {
        "id": 9,
        "text": "The ball shall be a square with a size of 1 x 2 blocks."
    },
    {
        "id": 10,
        "text": "The game shall award points to the player who kicks the ball to the goal."
    },
    {
        "id": 11,
        "text": "The game shall display the correct winning message when a player wins."
    },
    {
        "id": 12,
        "text": "The game shall reset to the normal conditions after a player scores a point."
    },
    {
        "id": 13,
        "text": "The ball shall move to one side depending on what is fair considering who lost the last round after a player scores a point."
    },
    {
        "id": 14,
        "text": "The ball's speed shall be increased by 10% of its current speed every time the ball hits the top or bottom of the board, or a paddle."
    },
    {
        "id": 15,
        "text": "The game shall allow the players to select between a 1 player mode and a 2 player mode."
    },
    {
        "id": 16,
        "text": "A dashed line shall separate the two sides of the board in the horizontal center of the board if possible."
    },
    {
        "id": 17,
        "text": "Numbers representing the current scores of both players shall be displayed at the top of the board vertically."
    },
    {
        "id": 18,
        "text": "The background of the board shall be black, and everything else shall be white."
    },
    {
        "id": 19,
        "text": "A beep sound shall be made every time the ball hits the top or bottom of the board."
    },
    {
        "id": 20,
        "text": "The first player's paddle shall be controlled by pressing the 'w' key for up and the 's' key for down."
    }
]}
